window.addEventListener('DOMContentLoaded', function () {
  setTimeout(function () {
    if (typeof $ === 'undefined' || !$.fn || !$.fn.magnificPopup) {
      return;
    }
    $('.popup-btn').magnificPopup({
      type: 'image',
      gallery: { enabled: true }
    });
    $('.image-link').magnificPopup({
      type: 'image',
      gallery: { enabled: true }
    });
  }, 0);
});
